export const dashboardHtml = "<!DOCTYPE html>\n<html lang=\"fr\" data-theme=\"light\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>ORL Platform — Backend API</title>\n<meta name=\"description\" content=\"Backend DEMS ORL Platform — API, Health & Realtime Dashboard\" />\n<meta name=\"theme-color\" content=\"#4f46e5\" />\n<link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='8' fill='%234f46e5'/%3E%3Cpath d='M16 8a8 8 0 0 0-8 8c0 3.5 2.2 6.5 5.5 7.7L16 26l2.5-2.3A8 8 0 0 0 24 16a8 8 0 0 0-8-8zm0 2a6 6 0 0 1 6 6c0 2.3-1.3 4.3-3.2 5.4L16 23.2l-2.8-1.8A6 6 0 0 1 10 16a6 6 0 0 1 6-6z' fill='white'/%3E%3Ccircle cx='16' cy='16' r='2.5' fill='white'/%3E%3C/svg%3E\" />\n<style>\n  :root{\n    --bg:#f8fafc;\n    --bg-soft:#f1f5f9;\n    --card:#ffffff;\n    --card-hover:#ffffff;\n    --text:#0f172a;\n    --text-soft:#334155;\n    --muted:#64748b;\n    --muted-2:#94a3b8;\n    --border:#e2e8f0;\n    --border-strong:#cbd5e1;\n    --primary:#4f46e5;\n    --primary-hover:#4338ca;\n    --primary-soft:#eef2ff;\n    --primary-ring:rgba(79,70,229,.18);\n    --success:#10b981;\n    --success-soft:#ecfdf5;\n    --success-ring:rgba(16,185,129,.18);\n    --warning:#f59e0b;\n    --warning-soft:#fffbeb;\n    --danger:#ef4444;\n    --danger-soft:#fef2f2;\n    --shadow:0 1px 3px rgba(15,23,42,.06),0 4px 16px rgba(15,23,42,.04);\n    --shadow-lg:0 4px 24px rgba(15,23,42,.08),0 12px 40px rgba(15,23,42,.06);\n    --radius:16px;\n    --radius-sm:10px;\n    --radius-xs:8px;\n    --max:1200px;\n  }\n  [data-theme=\"dark\"]{\n    --bg:#0b1220;\n    --bg-soft:#111a2e;\n    --card:#111d33;\n    --card-hover:#132040;\n    --text:#e6edf7;\n    --text-soft:#cbd5e1;\n    --muted:#8a9bb4;\n    --muted-2:#6b7fa0;\n    --border:#1e2d4a;\n    --border-strong:#24365c;\n    --primary:#6366f1;\n    --primary-hover:#818cf8;\n    --primary-soft:#1a1f3d;\n    --primary-ring:rgba(99,102,241,.25);\n    --success:#34d399;\n    --success-soft:#0f2a22;\n    --warning:#fbbf24;\n    --warning-soft:#2a2310;\n    --danger:#f87171;\n    --danger-soft:#2a1214;\n    --shadow:0 1px 3px rgba(0,0,0,.3),0 8px 24px rgba(0,0,0,.25);\n    --shadow-lg:0 8px 32px rgba(0,0,0,.35);\n  }\n  *{box-sizing:border-box}\n  html{scroll-behavior:smooth}\n  body{\n    margin:0;\n    font-family: ui-sans-system, -apple-system, BlinkMacSystemFont, \"SF Pro Display\",\"Inter\", \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n    background:var(--bg);\n    color:var(--text);\n    line-height:1.6;\n    -webkit-font-smoothing:antialiased;\n    transition: background .25s ease, color .25s ease;\n  }\n  a{color:var(--primary);text-decoration:none}\n  a:hover{text-decoration:underline}\n  button{font:inherit}\n  ::selection{background:var(--primary);color:white}\n  /* Header */\n  .topbar{\n    position:sticky;top:0;z-index:40;\n    backdrop-filter: saturate(1.2) blur(14px);\n    background: color-mix(in srgb, var(--card) 82%, transparent);\n    border-bottom:1px solid var(--border);\n  }\n  .topbar-inner{\n    max-width:var(--max);margin:0 auto;\n    padding:14px 20px;\n    display:flex;align-items:center;justify-content:space-between;gap:16px;\n  }\n  .brand{display:flex;align-items:center;gap:12px;min-width:0}\n  .brand-logo{\n    width:40px;height:40px;border-radius:11px;\n    background: linear-gradient(135deg, #4f46e5 0%, #7c3aed 50%, #06b6d4 100%);\n    display:grid;place-items:center;\n    box-shadow:0 4px 14px rgba(79,70,229,.3);\n    flex-shrink:0;\n  }\n  .brand-logo svg{width:22px;height:22px}\n  .brand-text h1{margin:0;font-size:15px;font-weight:750;letter-spacing:-.02em;line-height:1.1}\n  .brand-text p{margin:2px 0 0;font-size:12.5px;color:var(--muted);font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n  .top-actions{display:flex;align-items:center;gap:10px;flex-shrink:0}\n  .status-pill{\n    display:inline-flex;align-items:center;gap:8px;\n    padding:7px 12px;border-radius:999px;\n    background:var(--success-soft);border:1px solid color-mix(in srgb, var(--success) 18%, transparent);\n    font-size:12.5px;font-weight:650;color:color-mix(in srgb, var(--success) 85%, var(--text));\n  }\n  .status-dot{width:8px;height:8px;border-radius:50%;background:var(--success);box-shadow:0 0 0 4px var(--success-ring);animation:pulse 2s infinite}\n  .status-pill.offline{background:var(--danger-soft);border-color:color-mix(in srgb, var(--danger) 18%, transparent);color:var(--danger)}\n  .status-pill.offline .status-dot{background:var(--danger);box-shadow:0 0 0 4px color-mix(in srgb, var(--danger) 14%, transparent)}\n  @keyframes pulse{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.85;transform:scale(.96)}}\n  .icon-btn{\n    width:40px;height:40px;border-radius:10px;\n    border:1px solid var(--border);background:var(--card);\n    display:grid;place-items:center;cursor:pointer;\n    color:var(--muted);transition:all .15s;\n  }\n  .icon-btn:hover{border-color:var(--border-strong);color:var(--text);transform:translateY(-1px);box-shadow:var(--shadow)}\n  .icon-btn:active{transform:translateY(0)}\n  /* Layout */\n  .wrap{max-width:var(--max);margin:0 auto;padding:28px 20px 48px}\n  .hero{\n    display:grid;grid-template-columns:1.35fr .85fr;gap:18px;\n    margin:8px 0 22px;\n  }\n  @media(max-width:860px){.hero{grid-template-columns:1fr}}\n  .hero-card{\n    background: linear-gradient(135deg, color-mix(in srgb, var(--primary) 9%, var(--card)) 0%, var(--card) 55%);\n    border:1px solid var(--border);border-radius:var(--radius);\n    padding:22px;box-shadow:var(--shadow);\n    position:relative;overflow:hidden;\n  }\n  .hero-card::after{\n    content:\"\";position:absolute;inset:auto -30% -45% auto;width:380px;height:380px;\n    background: radial-gradient(closest-side, color-mix(in srgb, var(--primary) 10%, transparent), transparent 70%);\n    pointer-events:none;\n  }\n  .eyebrow{\n    display:inline-flex;align-items:center;gap:7px;\n    font-size:11px;font-weight:750;letter-spacing:.08em;text-transform:uppercase;\n    color:var(--primary);background:var(--primary-soft);\n    border:1px solid color-mix(in srgb, var(--primary) 12%, transparent);\n    padding:5px 9px;border-radius:999px;\n  }\n  .hero h2{margin:12px 0 8px;font-size:26px;line-height:1.15;letter-spacing:-.03em;font-weight:800}\n  .hero p{margin:0;color:var(--muted);font-size:14.5px;max-width:52ch}\n  .hero-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:18px;position:relative;z-index:1}\n  .btn{\n    display:inline-flex;align-items:center;gap:8px;\n    padding:10px 14px;border-radius:10px;\n    font-size:13.5px;font-weight:650;cursor:pointer;\n    border:1px solid transparent;transition:all .15s;\n    text-decoration:none !important;\n  }\n  .btn-primary{background:var(--primary);color:white;box-shadow:0 4px 14px var(--primary-ring)}\n  .btn-primary:hover{background:var(--primary-hover);transform:translateY(-1px)}\n  .btn-ghost{background:var(--card);border-color:var(--border);color:var(--text)}\n  .btn-ghost:hover{border-color:var(--border-strong);background:var(--card-hover);transform:translateY(-1px)}\n  .mini-stats{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n  .mini-card{\n    background:var(--card);border:1px solid var(--border);border-radius:14px;\n    padding:14px;box-shadow:var(--shadow);\n  }\n  .mini-card .k{font-size:11px;font-weight:750;letter-spacing:.07em;text-transform:uppercase;color:var(--muted)}\n  .mini-card .v{margin-top:6px;font-size:18px;font-weight:800;letter-spacing:-.02em}\n  .mini-card .s{margin-top:4px;font-size:12.5px;color:var(--muted)}\n  /* Stats grid */\n  .stats{\n    display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:18px;\n  }\n  @media(max-width:980px){.stats{grid-template-columns:repeat(2,1fr)}}\n  @media(max-width:520px){.stats{grid-template-columns:1fr}}\n  .stat{\n    background:var(--card);border:1px solid var(--border);border-radius:14px;\n    padding:16px;box-shadow:var(--shadow);\n    transition: transform .15s, box-shadow .15s, border-color .15s;\n  }\n  .stat:hover{transform:translateY(-2px);box-shadow:var(--shadow-lg);border-color:var(--border-strong)}\n  .stat-top{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}\n  .stat-icon{width:36px;height:36px;border-radius:10px;display:grid;place-items:center}\n  .stat-icon svg{width:18px;height:18px}\n  .stat-label{font-size:11px;font-weight:750;letter-spacing:.07em;text-transform:uppercase;color:var(--muted)}\n  .stat-value{font-size:22px;font-weight:850;letter-spacing:-.03em;line-height:1}\n  .stat-sub{margin-top:6px;font-size:12.5px;color:var(--muted);display:flex;align-items:center;gap:6px}\n  .badge{font-size:11px;font-weight:700;padding:3px 7px;border-radius:999px;border:1px solid var(--border);background:var(--bg-soft);color:var(--muted)}\n  .badge.ok{background:var(--success-soft);color:var(--success);border-color:color-mix(in srgb, var(--success) 18%, transparent)}\n  .badge.warn{background:var(--warning-soft);color:var(--warning);border-color:color-mix(in srgb, var(--warning) 18%, transparent)}\n  .badge.err{background:var(--danger-soft);color:var(--danger);border-color:color-mix(in srgb, var(--danger) 18%, transparent)}\n  /* Sections */\n  .section{margin-top:18px}\n  .section-head{display:flex;align-items:end;justify-content:space-between;gap:12px;margin-bottom:12px;flex-wrap:wrap}\n  .section-head h3{margin:0;font-size:16px;font-weight:800;letter-spacing:-.02em;display:flex;align-items:center;gap:9px}\n  .section-head h3 i{width:28px;height:28px;border-radius:8px;background:var(--primary-soft);border:1px solid color-mix(in srgb, var(--primary) 10%, transparent);display:grid;place-items:center;color:var(--primary)}\n  .section-head h3 i svg{width:16px;height:16px}\n  .section-head p{margin:0;font-size:13px;color:var(--muted)}\n  .card{\n    background:var(--card);border:1px solid var(--border);border-radius:var(--radius);\n    box-shadow:var(--shadow);overflow:hidden;\n  }\n  .card-pad{padding:18px}\n  .grid-2{display:grid;grid-template-columns:1fr 1fr;gap:14px}\n  @media(max-width:860px){.grid-2{grid-template-columns:1fr}}\n  /* Health */\n  .health-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:14px}\n  @media(max-width:860px){.health-grid{grid-template-columns:1fr}}\n  .code{\n    font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, \"Liberation Mono\", monospace;\n    font-size:12.5px;line-height:1.6;\n    background:var(--bg-soft);border:1px solid var(--border);\n    border-radius:10px;padding:12px;overflow:auto;max-height:240px;\n  }\n  .kv{display:grid;grid-template-columns:140px 1fr;gap:8px 14px;font-size:13px}\n  .kv dt{color:var(--muted);font-weight:600}\n  .kv dd{margin:0;font-weight:650;word-break:break-word}\n  .latency{font-variant-numeric:tabular-nums}\n  /* Tabs */\n  .tabs{display:flex;gap:6px;padding:6px;background:var(--bg-soft);border:1px solid var(--border);border-radius:12px;overflow:auto;scrollbar-width:none}\n  .tabs::-webkit-scrollbar{display:none}\n  .tab{\n    padding:8px 12px;border-radius:8px;border:1px solid transparent;\n    font-size:13px;font-weight:700;cursor:pointer;white-space:nowrap;\n    color:var(--muted);background:transparent;transition:all .15s;\n  }\n  .tab.active{background:var(--card);border-color:var(--border);color:var(--text);box-shadow:var(--shadow)}\n  .tab:hover{color:var(--text)}\n  .panel{display:none}\n  .panel.active{display:block}\n  .endpoint{\n    display:grid;grid-template-columns:auto 1fr auto;gap:10px;\n    align-items:center;\n    padding:12px 14px;border:1px solid var(--border);border-radius:12px;\n    background:var(--card);transition:all .15s;\n  }\n  .endpoint + .endpoint{margin-top:10px}\n  .endpoint:hover{border-color:var(--border-strong);transform:translateY(-1px);box-shadow:var(--shadow)}\n  .method{\n    font-size:11px;font-weight:850;letter-spacing:.06em;\n    padding:5px 7px;border-radius:7px;min-width:56px;text-align:center;\n    border:1px solid var(--border);\n  }\n  .method.get{background:#ecfdf5;color:#065f46;border-color:#a7f3d0}\n  [data-theme=\"dark\"] .method.get{background:#0f2a22;color:#6ee7b7;border-color:#1e4a3a}\n  .method.post{background:#eff6ff;color:#1e40af;border-color:#bfdbfe}\n  [data-theme=\"dark\"] .method.post{background:#131d3a;color:#93c5fd;border-color:#24365c}\n  .method.put{background:#fffbeb;color:#92400e;border-color:#fde68a}\n  [data-theme=\"dark\"] .method.put{background:#2a2310;color:#fcd34d;border-color:#4a3a18}\n  .method.patch{background:#fdf2f8;color:#9d174d;border-color:#fbcfe8}\n  [data-theme=\"dark\"] .method.patch{background:#2a1430;color:#f9a8d4;border-color:#4a2340}\n  .method.delete{background:#fef2f2;color:#991b1b;border-color:#fecaca}\n  [data-theme=\"dark\"] .method.delete{background:#2a1214;color:#fca5a5;border-color:#4a2020}\n  .ep-path{font-family:ui-monospace,monospace;font-size:13px;font-weight:700;letter-spacing:-.01em;word-break:break-all}\n  .ep-desc{font-size:12.5px;color:var(--muted);margin-top:2px}\n  .ep-actions{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}\n  .chip{\n    display:inline-flex;align-items:center;gap:5px;\n    font-size:11px;font-weight:700;padding:4px 7px;border-radius:999px;\n    border:1px solid var(--border);background:var(--bg-soft);color:var(--muted)\n  }\n  .chip.auth{color:var(--primary);border-color:color-mix(in srgb, var(--primary) 18%, transparent);background:var(--primary-soft)}\n  .small-btn{\n    padding:7px 9px;border-radius:8px;border:1px solid var(--border);\n    background:var(--card);font-size:12px;font-weight:700;cursor:pointer;\n    color:var(--text);transition:all .15s;\n  }\n  .small-btn:hover{border-color:var(--border-strong);transform:translateY(-1px)}\n  .small-btn.primary{background:var(--primary);border-color:var(--primary);color:white}\n  .small-btn.primary:hover{background:var(--primary-hover)}\n  /* realtime */\n  .version-item{\n    display:flex;align-items:center;justify-content:space-between;gap:12px;\n    padding:10px 12px;border:1px solid var(--border);border-radius:10px;background:var(--bg-soft);\n  }\n  .version-item + .version-item{margin-top:8px}\n  .version-name{font-size:13px;font-weight:700}\n  .version-meta{font-size:12px;color:var(--muted);display:flex;gap:10px;flex-wrap:wrap}\n  /* footer */\n  footer{margin-top:28px;padding:18px 0 0;border-top:1px solid var(--border);display:flex;flex-wrap:wrap;gap:12px;align-items:center;justify-content:space-between;font-size:12.5px;color:var(--muted)}\n  .foot-links{display:flex;gap:12px;flex-wrap:wrap}\n  .foot-links a{color:var(--muted);font-weight:600}\n  .foot-links a:hover{color:var(--text)}\n  /* toast */\n  .toast{\n    position:fixed;right:16px;bottom:16px;z-index:50;\n    background:var(--text);color:var(--bg);\n    padding:10px 12px;border-radius:10px;font-size:13px;font-weight:600;\n    box-shadow:var(--shadow-lg);transform:translateY(12px);opacity:0;pointer-events:none;\n    transition:all .2s;\n  }\n  .toast.show{transform:translateY(0);opacity:1}\n  /* skeleton */\n  .skeleton{height:12px;border-radius:999px;background:linear-gradient(90deg, var(--bg-soft) 25%, color-mix(in srgb, var(--border) 60%, var(--bg-soft)) 50%, var(--bg-soft) 75%);background-size:200% 100%;animation:shimmer 1.2s infinite}\n  @keyframes shimmer{0%{background-position:200% 0}100%{background-position:-200% 0}}\n  /* scrollbar */\n  *{scrollbar-width:thin;scrollbar-color:var(--border-strong) transparent}\n  *::-webkit-scrollbar{width:8px;height:8px}\n  *::-webkit-scrollbar-thumb{background:var(--border-strong);border-radius:999px}\n  *::-webkit-scrollbar-track{background:transparent}\n</style>\n</head>\n<body>\n<header class=\"topbar\">\n  <div class=\"topbar-inner\">\n    <div class=\"brand\">\n      <div class=\"brand-logo\" aria-hidden=\"true\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M12 3a7 7 0 0 0-7 7c0 3 1.9 5.6 4.7 6.7L12 19l2.3-2.3A7 7 0 0 0 19 10a7 7 0 0 0-7-7Z\" stroke=\"white\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/><circle cx=\"12\" cy=\"10\" r=\"2.2\" fill=\"white\"/></svg>\n      </div>\n      <div class=\"brand-text\">\n        <h1>ORL Platform — Backend</h1>\n        <p>DEMS • API &amp; Health Dashboard</p>\n      </div>\n    </div>\n    <div class=\"top-actions\">\n      <div id=\"statusPill\" class=\"status-pill\" title=\"Statut global du service\">\n        <span class=\"status-dot\"></span>\n        <span id=\"statusText\">Vérification…</span>\n      </div>\n      <button id=\"themeToggle\" class=\"icon-btn\" aria-label=\"Basculer thème clair/sombre\" title=\"Thème clair/sombre\">\n        <svg id=\"iconSun\" viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2v2M12 20v2M4.93 4.93l1.42 1.42M17.66 17.66l1.42 1.42M2 12h2M20 12h2M4.93 19.07l1.42-1.42M17.66 6.34l1.42-1.42\"/></svg>\n        <svg id=\"iconMoon\" viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" style=\"display:none\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79Z\"/></svg>\n      </button>\n    </div>\n  </div>\n</header>\n\n<main class=\"wrap\">\n  <!-- HERO -->\n  <section class=\"hero\">\n    <div class=\"hero-card\">\n      <span class=\"eyebrow\"><span style=\"width:7px;height:7px;border-radius:50%;background:var(--success);display:inline-block;box-shadow:0 0 0 4px var(--success-ring)\"></span> Backend opérationnel</span>\n      <h2>L’API DEMS sous contrôle, en temps réel</h2>\n      <p>Surveillez la santé du service, explorez les endpoints, testez les routes et suivez les collections — directement depuis l’URL racine du backend, sans passer par le frontend.</p>\n      <div class=\"hero-actions\">\n        <a class=\"btn btn-primary\" href=\"#health\">⟡ Vérifier la santé</a>\n        <a class=\"btn btn-ghost\" href=\"#api\">▦ Explorer l’API</a>\n        <button class=\"btn btn-ghost\" id=\"btnCopyBaseUrl\" type=\"button\">⧉ Copier Base URL</button>\n      </div>\n    </div>\n    <div class=\"mini-stats\">\n      <div class=\"mini-card\">\n        <div class=\"k\">Base URL</div>\n        <div id=\"baseUrl\" class=\"v\" style=\"font-size:14px;word-break:break-all\">—</div>\n        <div class=\"s\">Racine actuelle • <span id=\"envInline\">—</span></div>\n      </div>\n      <div class=\"mini-card\">\n        <div class=\"k\">Latence</div>\n        <div id=\"latencyHero\" class=\"v\">—</div>\n        <div class=\"s\"><span id=\"lastCheck\">jamais</span> • auto 5s</div>\n      </div>\n      <div class=\"mini-card\">\n        <div class=\"k\">Service</div>\n        <div id=\"serviceName\" class=\"v\" style=\"font-size:15px\">orl-platform-dems-backend</div>\n        <div class=\"s\" id=\"serviceVersion\">v1.0.0 • Node —</div>\n      </div>\n      <div class=\"mini-card\">\n        <div class=\"k\">Uptime</div>\n        <div id=\"uptimeHero\" class=\"v\">—</div>\n        <div class=\"s\" id=\"timestampHero\">—</div>\n      </div>\n    </div>\n  </section>\n\n  <!-- STATS -->\n  <section class=\"stats\" aria-label=\"Statistiques\">\n    <div class=\"stat\">\n      <div class=\"stat-top\">\n        <div class=\"stat-icon\" style=\"background:var(--success-soft);color:var(--success);border:1px solid color-mix(in srgb, var(--success) 16%, transparent)\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M22 12h-4l-3 9L9 3l-3 9H2\"/><circle cx=\"12\" cy=\"12\" r=\"9\" stroke-opacity=\".18\"/></svg></div>\n        <span id=\"mongoBadge\" class=\"badge\">—</span>\n      </div>\n      <div class=\"stat-label\">MongoDB</div>\n      <div id=\"mongoValue\" class=\"stat-value\">—</div>\n      <div class=\"stat-sub\"><span id=\"mongoDbName\">—</span> • <span id=\"mongoLatency\">—</span></div>\n    </div>\n    <div class=\"stat\">\n      <div class=\"stat-top\">\n        <div class=\"stat-icon\" style=\"background:var(--primary-soft);color:var(--primary);border:1px solid color-mix(in srgb, var(--primary) 14%, transparent)\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"3\"/><path d=\"M8 12h8M12 8v8\"/></svg></div>\n        <span class=\"badge\">Realtime</span>\n      </div>\n      <div class=\"stat-label\">Collections surveillées</div>\n      <div id=\"watchedValue\" class=\"stat-value\">13</div>\n      <div class=\"stat-sub\">Hash <span id=\"hashValue\" style=\"font-family:monospace\">—</span> • <span id=\"realtimeTs\">—</span></div>\n    </div>\n    <div class=\"stat\">\n      <div class=\"stat-top\">\n        <div class=\"stat-icon\" style=\"background:var(--warning-soft);color:#b45309;border:1px solid color-mix(in srgb, var(--warning) 18%, transparent)\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M12 2l9 16H3L12 2Z\"/><path d=\"M12 9v5M12 17h.01\"/></svg></div>\n        <span class=\"badge\">CORS</span>\n      </div>\n      <div class=\"stat-label\">Origines autorisées</div>\n      <div id=\"corsValue\" class=\"stat-value\">—</div>\n      <div class=\"stat-sub\" id=\"corsOrigins\">—</div>\n    </div>\n    <div class=\"stat\">\n      <div class=\"stat-top\">\n        <div class=\"stat-icon\" style=\"background:#fef2f8;color:#be185d;border:1px solid #fbcfe8\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M14 2H7a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8Z\"/><path d=\"M14 2v6h6\"/><path d=\"M10 13H8M16 17H8M13 13h2\"/></svg></div>\n        <span class=\"badge\">Env</span>\n      </div>\n      <div class=\"stat-label\">Environnement</div>\n      <div id=\"envValue\" class=\"stat-value\">—</div>\n      <div class=\"stat-sub\" id=\"platformValue\">— • —</div>\n    </div>\n  </section>\n\n  <!-- HEALTH -->\n  <section id=\"health\" class=\"section\">\n    <div class=\"section-head\">\n      <h3><i><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M22 12h-4l-3 9L9 3l-3 9H2\"/></svg></i> Santé &amp; Diagnostics</h3>\n      <p>Endpoints <code>/api/health</code> et <code>/health</code> • polling auto 5s</p>\n    </div>\n    <div class=\"health-grid\">\n      <div class=\"card\">\n        <div class=\"card-pad\">\n          <div style=\"display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:12px\">\n            <strong style=\"font-size:13px;letter-spacing:-.01em\">Réponse live — /api/health</strong>\n            <span style=\"display:flex;gap:8px;align-items:center\">\n              <span id=\"healthStatus\" class=\"badge\">—</span>\n              <span id=\"healthLatency\" class=\"badge latency\">— ms</span>\n            </span>\n          </div>\n          <pre id=\"healthJson\" class=\"code\" aria-live=\"polite\">Chargement…</pre>\n          <div style=\"display:flex;gap:8px;flex-wrap:wrap;margin-top:12px\">\n            <button class=\"small-btn primary\" id=\"btnRefreshHealth\" type=\"button\">↻ Rafraîchir</button>\n            <button class=\"small-btn\" id=\"btnCopyHealth\" type=\"button\">⧉ Copier JSON</button>\n            <a class=\"small-btn\" href=\"/api/health\" target=\"_blank\" rel=\"noopener\">↗ Ouvrir /api/health</a>\n            <a class=\"small-btn\" href=\"/health\" target=\"_blank\" rel=\"noopener\">↗ /health</a>\n          </div>\n          <dl class=\"kv\" style=\"margin-top:14px\">\n            <dt>Service</dt><dd id=\"kvService\">—</dd>\n            <dt>Mongo</dt><dd id=\"kvMongo\">—</dd>\n            <dt>Uptime</dt><dd id=\"kvUptime\">—</dd>\n            <dt>Timestamp</dt><dd id=\"kvTimestamp\">—</dd>\n            <dt>Node</dt><dd id=\"kvNode\">—</dd>\n          </dl>\n        </div>\n      </div>\n      <div class=\"card\">\n        <div class=\"card-pad\">\n          <strong style=\"font-size:13px\">Realtime — versions des collections</strong>\n          <p style=\"margin:6px 0 12px;color:var(--muted);font-size:13px\"><code>/api/realtime/versions</code> • cache 1.5s • idéal pour détecter les changements.</p>\n          <div style=\"display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px\">\n            <button class=\"small-btn primary\" id=\"btnRefreshVersions\" type=\"button\">↻ Rafraîchir</button>\n            <button class=\"small-btn\" id=\"btnSse\" type=\"button\">● SSE Stream</button>\n            <a class=\"small-btn\" href=\"/api/realtime/versions\" target=\"_blank\" rel=\"noopener\">↗ Ouvrir JSON</a>\n          </div>\n          <div id=\"versionsList\" style=\"max-height:272px;overflow:auto;padding-right:2px\">\n            <div class=\"skeleton\" style=\"height:44px;border-radius:10px\"></div>\n            <div class=\"skeleton\" style=\"height:44px;border-radius:10px;margin-top:8px\"></div>\n            <div class=\"skeleton\" style=\"height:44px;border-radius:10px;margin-top:8px\"></div>\n          </div>\n          <div id=\"sseLog\" class=\"code\" style=\"display:none;margin-top:12px;max-height:140px\"></div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- API CATALOG -->\n  <section id=\"api\" class=\"section\">\n    <div class=\"section-head\">\n      <h3><i><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.5\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.5\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.5\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.5\"/></svg></i> Catalogue API</h3>\n      <p>Copiez le <code>curl</code> ou testez directement (Bearer token optionnel).</p>\n    </div>\n    <div class=\"card\">\n      <div class=\"card-pad\">\n        <div style=\"display:flex;gap:10px;flex-wrap:wrap;align-items:center;justify-content:space-between;margin-bottom:14px\">\n          <div class=\"tabs\" role=\"tablist\" aria-label=\"Catégories d'endpoints\">\n            <button class=\"tab active\" data-tab=\"auth\" role=\"tab\" aria-selected=\"true\">Auth &amp; Google</button>\n            <button class=\"tab\" data-tab=\"data\" role=\"tab\">Data &amp; Collections</button>\n            <button class=\"tab\" data-tab=\"uploads\" role=\"tab\">Uploads &amp; Cloudinary</button>\n            <button class=\"tab\" data-tab=\"realtime\" role=\"tab\">Realtime</button>\n            <button class=\"tab\" data-tab=\"contact\" role=\"tab\">Contact</button>\n            <button class=\"tab\" data-tab=\"system\" role=\"tab\">System</button>\n          </div>\n          <div style=\"display:flex;gap:8px;align-items:center;flex-wrap:wrap\">\n            <input id=\"apiSearch\" placeholder=\"Filtrer… /health, auth, video\" style=\"padding:8px 10px;border-radius:9px;border:1px solid var(--border);background:var(--bg-soft);color:var(--text);font-size:13px;min-width:220px;outline:none\" />\n            <input id=\"tokenInput\" placeholder=\"Bearer token (optionnel)\" style=\"padding:8px 10px;border-radius:9px;border:1px solid var(--border);background:var(--bg-soft);color:var(--text);font-size:13px;min-width:220px;outline:none\" />\n          </div>\n        </div>\n\n        <!-- AUTH -->\n        <div class=\"panel active\" data-panel=\"auth\">\n          <div class=\"endpoint\" data-keywords=\"auth signup signin inscription connexion\">\n            <span class=\"method post\">POST</span>\n            <div><div class=\"ep-path\">/api/auth/signup</div><div class=\"ep-desc\">Création de compte — email, password ≥6, displayName</div></div>\n            <div class=\"ep-actions\"><span class=\"chip\">public</span><button class=\"small-btn\" data-copy=\"curl -X POST BASE/api/auth/signup -H 'Content-Type: application/json' -d '{\\&quot;email\\&quot;:\\&quot;test@ex.com\\&quot;,\\&quot;password\\&quot;:\\&quot;secret12\\&quot;,\\&quot;displayName\\&quot;:\\&quot;Test\\&quot;}'\">⧉ curl</button><button class=\"small-btn primary\" data-try=\"/api/auth/signup\" data-method=\"POST\">Try</button></div>\n          </div>\n          <div class=\"endpoint\" data-keywords=\"auth signin login\">\n            <span class=\"method post\">POST</span>\n            <div><div class=\"ep-path\">/api/auth/signin</div><div class=\"ep-desc\">Connexion — email + password → token + user</div></div>\n            <div class=\"ep-actions\"><span class=\"chip\">public</span><button class=\"small-btn\" data-copy=\"curl -X POST BASE/api/auth/signin -H 'Content-Type: application/json' -d '{\\&quot;email\\&quot;:\\&quot;test@ex.com\\&quot;,\\&quot;password\\&quot;:\\&quot;secret12\\&quot;}'\">⧉ curl</button><button class=\"small-btn primary\" data-try=\"/api/auth/signin\" data-method=\"POST\">Try</button></div>\n          </div>\n          <div class=\"endpoint\" data-keywords=\"auth forgot reset password\">\n            <span class=\"method post\">POST</span>\n            <div><div class=\"ep-path\">/api/auth/forgot-password</div><div class=\"ep-desc\">Demande reset — email → lien (30 min) + email si SMTP configuré</div></div>\n            <div class=\"ep-actions\"><span class=\"chip\">public</span><button class=\"small-btn\" data-copy=\"curl -X POST BASE/api/auth/forgot-password -H 'Content-Type: application/json' -d '{\\&quot;email\\&quot;:\\&quot;test@ex.com\\&quot;}'\">⧉ curl</button></div>\n          </div>\n          <div class=\"endpoint\" data-keywords=\"auth reset password token\">\n            <span class=\"method post\">POST</span>\n            <div><div class=\"ep-path\">/api/auth/reset-password</div><div class=\"ep-desc\">Reset — token + newPassword ≥6</div></div>\n            <div class=\"ep-actions\"><span class=\"chip\">public</span><button class=\"small-btn\" data-copy=\"curl -X POST BASE/api/auth/reset-password -H 'Content-Type: application/json' -d '{\\&quot;token\\&quot;:\\&quot;...&quot;,\\&quot;newPassword\\&quot;:\\&quot;newpass12\\&quot;}'\">⧉ curl</button></div>\n          </div>\n          <div class=\"endpoint\" data-keywords=\"auth me profile\">\n            <span class=\"method get\">GET</span>\n            <div><div class=\"ep-path\">/api/auth/me</div><div class=\"ep-desc\">Session courante — Authorization: Bearer &lt;token&gt;</div></div>\n            <div class=\"ep-actions\"><span class=\"chip auth\">auth</span><button class=\"small-btn\" data-copy=\"curl BASE/api/auth/me -H 'Authorization: Bearer TOKEN'\">⧉ curl</button><button class=\"small-btn primary\" data-try=\"/api/auth/me\" data-method=\"GET\">Try</button></div>\n          </div>\n          <div class=\"endpoint\" data-keywords=\"auth profile patch\">\n            <span class=\"method patch\">PATCH</span>\n            <div><div class=\"ep-path\">/api/auth/profile</div><div class=\"ep-desc\">Màj profil — displayName, photoURL (uid optionnel si admin)</div></div>\n            <div class=\"ep-actions\"><span class=\"chip auth\">auth</span><button class=\"small-btn\" data-copy=\"curl -X PATCH BASE/api/auth/profile -H 'Authorization: Bearer TOKEN' -H 'Content-Type: application/json' -d '{\\&quot;displayName\\&quot;:\\&quot;Dr. Nom\\&quot;}'\">⧉ curl</button></div>\n          </div>\n          <div class=\"endpoint\" data-keywords=\"auth change password\">\n            <span class=\"method post\">POST</span>\n            <div><div class=\"ep-path\">/api/auth/change-password</div><div class=\"ep-desc\">Changer mot de passe — currentPassword + newPassword (ou Google lié)</div></div>\n            <div class=\"ep-actions\"><span class=\"chip auth\">auth</span><button class=\"small-btn\" data-copy=\"curl -X POST BASE/api/auth/change-password -H 'Authorization: Bearer TOKEN' -H 'Content-Type: application/json' -d '{\\&quot;currentPassword\\&quot;:\\&quot;old12\\&quot;,\\&quot;newPassword\\&quot;:\\&quot;new12\\&quot;}'\">⧉ curl</button></div>\n          </div>\n          <div class=\"endpoint\" data-keywords=\"google oauth start callback\">\n            <span class=\"method get\">GET</span>\n            <div><div class=\"ep-path\">/api/auth/google/start?remember=&amp;next=</div><div class=\"ep-desc\">OAuth Google — redirection vers consent screen</div></div>\n            <div class=\"ep-actions\"><span class=\"chip\">public</span><a class=\"small-btn\" href=\"/api/auth/google/start\" target=\"_blank\" rel=\"noopener\">↗ Ouvrir</a></div>\n          </div>\n          <div class=\"endpoint\" data-keywords=\"google connect disconnect\">\n            <span class=\"method post\">POST</span>\n            <div><div class=\"ep-path\">/api/auth/google/connect-start • /api/auth/google/disconnect</div><div class=\"ep-desc\">Lier / délier Google — authRequired (disconnect peut prendre newPassword)</div></div>\n            <div class=\"ep-actions\"><span class=\"chip auth\">auth</span><button class=\"small-btn\" data-copy=\"curl -X POST BASE/api/auth/google/connect-start -H 'Authorization: Bearer TOKEN' -H 'Content-Type: application/json' -d '{}'\">⧉ curl</button></div>\n          </div>\n          <div class=\"endpoint\" data-keywords=\"admin create users delete seed\">\n            <span class=\"method post\">POST</span>\n            <div><div class=\"ep-path\">/api/auth/admin-create • DELETE /api/auth/users/:uid • POST /api/auth/seed-demo</div><div class=\"ep-desc\">Admin — création utilisateurs, suppression, seed INITIAL_ADMIN_ACCOUNTS</div></div>\n            <div class=\"ep-actions\"><span class=\"chip auth\">admin</span><button class=\"small-btn\" data-copy=\"curl -X POST BASE/api/auth/seed-demo\">⧉ curl</button></div>\n          </div>\n        </div>\n\n        <!-- DATA -->\n        <div class=\"panel\" data-panel=\"data\">\n          <div class=\"endpoint\" data-keywords=\"data collections videos qcms\">\n            <span class=\"method get\">GET</span>\n            <div><div class=\"ep-path\">/api/data/:collection</div><div class=\"ep-desc\">Lister une collection — videos, qcms, openQuestions, clinicalCases, diagrams, users, etc.</div></div>\n            <div class=\"ep-actions\"><span class=\"chip\">public*</span><button class=\"small-btn\" data-copy=\"curl BASE/api/data/videos\">⧉ curl</button><button class=\"small-btn primary\" data-try=\"/api/data/videos\" data-method=\"GET\">Try</button></div>\n          </div>\n          <div class=\"endpoint\" data-keywords=\"data query filter constraints\">\n            <span class=\"method post\">POST</span>\n            <div><div class=\"ep-path\">/api/data/query</div><div class=\"ep-desc\">Requête filtrée — { collection, constraints: [{ fieldPath, operator, value }] }</div></div>\n            <div class=\"ep-actions\"><span class=\"chip\">public*</span><button class=\"small-btn\" data-copy=\"curl -X POST BASE/api/data/query -H 'Content-Type: application/json' -d '{\\&quot;collection\\&quot;:\\&quot;videos\\&quot;,\\&quot;constraints\\&quot;:[]}'\">⧉ curl</button></div>\n          </div>\n          <div class=\"endpoint\" data-keywords=\"data import qcm open question\">\n            <span class=\"method post\">POST</span>\n            <div><div class=\"ep-path\">/api/data/qcms/import • /openQuestions/import • /clinicalCases/import • /diagrams/import</div><div class=\"ep-desc\">Imports groupés — rows[], déduplication, création vidéos placeholder, upload Drive → Cloudinary</div></div>\n            <div class=\"ep-actions\"><span class=\"chip\">public*</span><button class=\"small-btn\" data-copy=\"curl -X POST BASE/api/data/qcms/import -H 'Content-Type: application/json' -d '{\\&quot;rows\\&quot;:[]}'\">⧉ curl</button></div>\n          </div>\n          <div class=\"endpoint\" data-keywords=\"data crud get post put patch delete\">\n            <span class=\"method get\">GET</span>\n            <div><div class=\"ep-path\">GET /api/data/:collection/:id • POST /:collection • PUT /:collection/:id • PATCH /:collection/:id • DELETE /:collection/:id</div><div class=\"ep-desc\">CRUD générique — users via uid, autres via _id / ObjectId; PATCH supporte arrayUnion/arrayRemove</div></div>\n            <div class=\"ep-actions\"><span class=\"chip\">public*</span><button class=\"small-btn\" data-copy=\"curl BASE/api/data/videos/ID\">⧉ curl</button></div>\n          </div>\n          <p style=\"margin:12px 2px 0;color:var(--muted);font-size:12.5px\">* Certaines écritures vérifient <code>isCloudinarySettingsDoc</code> → adminOnly pour <code>users-cloudinary-settings</code>. Les collections sensibles (videos, qcms, clinicalCases, diagrams) ont garde-fou anti-duplicata.</p>\n        </div>\n\n        <!-- UPLOADS -->\n        <div class=\"panel\" data-panel=\"uploads\">\n          <div class=\"endpoint\" data-keywords=\"upload cloudinary video image raw\">\n            <span class=\"method post\">POST</span>\n            <div><div class=\"ep-path\">/api/uploads/cloudinary?resourceType=video&amp;folder=&amp;specialty=&amp;videoTitle=&amp;subFolder=</div><div class=\"ep-desc\">Upload — multipart file, ≤1024 MB, split ffmpeg &gt;100 MB, préflight anti-doublon publicId</div></div>\n            <div class=\"ep-actions\"><span class=\"chip auth\">auth</span><button class=\"small-btn\" data-copy=\"curl -X POST 'BASE/api/uploads/cloudinary?resourceType=video' -H 'Authorization: Bearer TOKEN' -F file=@video.mp4\">⧉ curl</button></div>\n          </div>\n          <div class=\"endpoint\" data-keywords=\"upload cloudinary delete\">\n            <span class=\"method delete\">DELETE</span>\n            <div><div class=\"ep-path\">/api/uploads/cloudinary?publicId=&amp;resourceType=</div><div class=\"ep-desc\">Suppression asset Cloudinary — image | video | raw</div></div>\n            <div class=\"ep-actions\"><span class=\"chip auth\">auth</span><button class=\"small-btn\" data-copy=\"curl -X DELETE 'BASE/api/uploads/cloudinary?publicId=orl-platform/videos/...&resourceType=video' -H 'Authorization: Bearer TOKEN'\">⧉ curl</button></div>\n          </div>\n          <div class=\"endpoint\" data-keywords=\"upload cleanup cloudinary\">\n            <span class=\"method post\">POST</span>\n            <div><div class=\"ep-path\">/api/uploads/cleanup</div><div class=\"ep-desc\">Nettoyage — { assets: [{ publicId, secureUrl, resourceType }] } ≤200, vérif. usage Mongo avant suppression</div></div>\n            <div class=\"ep-actions\"><span class=\"chip auth\">auth</span><button class=\"small-btn\" data-copy=\"curl -X POST BASE/api/uploads/cleanup -H 'Authorization: Bearer TOKEN' -H 'Content-Type: application/json' -d '{\\&quot;assets\\&quot;:[]}'\">⧉ curl</button></div>\n          </div>\n          <div class=\"endpoint\" data-keywords=\"upload avatar image\">\n            <span class=\"method post\">POST</span>\n            <div><div class=\"ep-path\">/api/uploads/avatar</div><div class=\"ep-desc\">Avatar — mémoire 10 MB, dossier orl-platform/avatars/&lt;name-user&gt;/</div></div>\n            <div class=\"ep-actions\"><span class=\"chip auth\">auth</span><button class=\"small-btn\" data-copy=\"curl -X POST BASE/api/uploads/avatar -H 'Authorization: Bearer TOKEN' -F file=@avatar.jpg\">⧉ curl</button></div>\n          </div>\n          <p style=\"margin:12px 2px 0;color:var(--muted);font-size:12.5px\">Dossiers organisés: <code>orl-platform/videos/&lt;specialité&gt;/&lt;vidéo&gt;/</code>, <code>cas-images</code>, <code>cas-question-images</code>, <code>diagrams</code>, <code>avatars</code>, <code>support-chat</code>.</p>\n        </div>\n\n        <!-- REALTIME -->\n        <div class=\"panel\" data-panel=\"realtime\">\n          <div class=\"endpoint\" data-keywords=\"realtime versions polling hash\">\n            <span class=\"method get\">GET</span>\n            <div><div class=\"ep-path\">/api/realtime/versions</div><div class=\"ep-desc\">Polling léger — count + updatedAt par collection, hash global, cache 1.5s</div></div>\n            <div class=\"ep-actions\"><span class=\"chip\">public</span><button class=\"small-btn primary\" data-try=\"/api/realtime/versions\" data-method=\"GET\">Try</button><button class=\"small-btn\" data-copy=\"curl BASE/api/realtime/versions\">⧉ curl</button></div>\n          </div>\n          <div class=\"endpoint\" data-keywords=\"realtime stream sse event source\">\n            <span class=\"method get\">GET</span>\n            <div><div class=\"ep-path\">/api/realtime/stream</div><div class=\"ep-desc\">SSE — text/event-stream toutes les 3s + heartbeat 15s</div></div>\n            <div class=\"ep-actions\"><span class=\"chip\">public</span><button class=\"small-btn\" id=\"btnCopySse\" data-copy=\"const es = new EventSource(BASE+'/api/realtime/stream'); es.onmessage = e => console.log(JSON.parse(e.data))\">⧉ JS</button><a class=\"small-btn\" href=\"/api/realtime/stream\" target=\"_blank\" rel=\"noopener\">↗ Ouvrir</a></div>\n          </div>\n          <p style=\"margin:12px 2px 0;color:var(--muted);font-size:12.5px\">Collections: videos, qcms, openQuestions, clinicalCases, diagrams, users, payments, notifications, supportChats, supportChatMessages, pedagogicalFeedback, clinicalCaseFeedback, appSettings.</p>\n        </div>\n\n        <!-- CONTACT -->\n        <div class=\"panel\" data-panel=\"contact\">\n          <div class=\"endpoint\" data-keywords=\"contact form email smtp\">\n            <span class=\"method post\">POST</span>\n            <div><div class=\"ep-path\">/api/contact</div><div class=\"ep-desc\">Contact — { name, email, phone?, subject, message, website(honeypot) } • rate-limit 5 / 15min</div></div>\n            <div class=\"ep-actions\"><span class=\"chip\">public</span><button class=\"small-btn\" data-copy=\"curl -X POST BASE/api/contact -H 'Content-Type: application/json' -d '{\\&quot;name\\&quot;:\\&quot;Test\\&quot;,\\&quot;email\\&quot;:\\&quot;a@b.com\\&quot;,\\&quot;subject\\&quot;:\\&quot;Support\\&quot;,\\&quot;message\\&quot;:\\&quot;Hello\\&quot;}'\">⧉ curl</button><button class=\"small-btn primary\" data-try=\"/api/contact\" data-method=\"POST\">Try</button></div>\n          </div>\n          <div class=\"endpoint\" data-keywords=\"contact health smtp\">\n            <span class=\"method get\">GET</span>\n            <div><div class=\"ep-path\">/api/contact/health</div><div class=\"ep-desc\">Diag contact — { ok, smtpConfigured, recipient }</div></div>\n            <div class=\"ep-actions\"><span class=\"chip\">public</span><button class=\"small-btn primary\" data-try=\"/api/contact/health\" data-method=\"GET\">Try</button></div>\n          </div>\n        </div>\n\n        <!-- SYSTEM -->\n        <div class=\"panel\" data-panel=\"system\">\n          <div class=\"endpoint\" data-keywords=\"system health meta\">\n            <span class=\"method get\">GET</span>\n            <div><div class=\"ep-path\">/api/health • /health • /api/meta</div><div class=\"ep-desc\">Santé — /api/health &amp; /health (ok, service, mongoConnected) • /api/meta (uptime, version, env, node, cors…)</div></div>\n            <div class=\"ep-actions\"><span class=\"chip\">public</span><button class=\"small-btn primary\" data-try=\"/api/meta\" data-method=\"GET\">Try /api/meta</button><button class=\"small-btn\" data-copy=\"curl BASE/api/meta\">⧉ curl</button></div>\n          </div>\n          <div class=\"endpoint\" data-keywords=\"system root dashboard\">\n            <span class=\"method get\">GET</span>\n            <div><div class=\"ep-path\">GET /  (ce dashboard)</div><div class=\"ep-desc\">Racine — sert ce dashboard HTML (text/html) ou JSON si Accept: application/json</div></div>\n            <div class=\"ep-actions\"><span class=\"chip\">public</span><a class=\"small-btn\" href=\"/\" target=\"_blank\" rel=\"noopener\">↗ Ouvrir</a></div>\n          </div>\n          <div class=\"endpoint\" data-keywords=\"system env cors\">\n            <span class=\"method get\">GET</span>\n            <div><div class=\"ep-path\">CORS &amp; Env</div><div class=\"ep-desc\" id=\"systemEnvDesc\">—</div></div>\n            <div class=\"ep-actions\"><span class=\"chip\">info</span></div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- DETAILS / DIO -->\n  <section class=\"section\">\n    <div class=\"grid-2\">\n      <div class=\"card\">\n        <div class=\"card-pad\">\n          <strong style=\"font-size:13px\">Tester un endpoint</strong>\n          <p style=\"margin:6px 0 12px;color:var(--muted);font-size:13px\">Sélectionnez “Try” sur un endpoint ou lancez une requête custom.</p>\n          <div style=\"display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px\">\n            <select id=\"tryMethod\" style=\"padding:8px 10px;border-radius:9px;border:1px solid var(--border);background:var(--bg-soft);color:var(--text);font-size:13px\">\n              <option>GET</option><option>POST</option><option>PUT</option><option>PATCH</option><option>DELETE</option>\n            </select>\n            <input id=\"tryPath\" value=\"/api/health\" style=\"flex:1;min-width:180px;padding:8px 10px;border-radius:9px;border:1px solid var(--border);background:var(--bg-soft);color:var(--text);font-size:13px\" />\n            <button class=\"small-btn primary\" id=\"btnTryCustom\" type=\"button\">Envoyer</button>\n          </div>\n          <textarea id=\"tryBody\" placeholder='Body JSON (pour POST/PUT/PATCH)' rows=\"3\" style=\"width:100%;padding:10px;border-radius:9px;border:1px solid var(--border);background:var(--bg-soft);color:var(--text);font-size:13px;font-family:ui-monospace,monospace;resize:vertical\"></textarea>\n          <pre id=\"tryResult\" class=\"code\" style=\"margin-top:10px;max-height:220px\">—</pre>\n        </div>\n      </div>\n      <div class=\"card\">\n        <div class=\"card-pad\">\n          <strong style=\"font-size:13px\">Journal live</strong>\n          <p style=\"margin:6px 0 12px;color:var(--muted);font-size:13px\">Derniers checks, erreurs et évènements SSE.</p>\n          <div id=\"log\" class=\"code\" style=\"max-height:340px;overflow:auto;font-size:12px;line-height:1.5\">—</div>\n          <div style=\"display:flex;gap:8px;margin-top:10px\">\n            <button class=\"small-btn\" id=\"btnClearLog\" type=\"button\">Effacer</button>\n            <button class=\"small-btn\" id=\"btnCopyLog\" type=\"button\">⧉ Copier</button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <footer>\n    <div>© 2026 DEMS — ORL Platform • Backend <span id=\"footService\">orl-platform-dems-backend</span> • <span id=\"footEnv\">—</span> • <a href=\"/api/health\">/api/health</a> • <a href=\"/api/meta\">/api/meta</a></div>\n    <div class=\"foot-links\">\n      <a href=\"#health\">Santé</a>\n      <a href=\"#api\">API</a>\n      <a href=\"/api/realtime/versions\" target=\"_blank\" rel=\"noopener\">Versions</a>\n      <span id=\"footTime\" style=\"font-variant-numeric:tabular-nums\">—</span>\n    </div>\n  </footer>\n</main>\n\n<div id=\"toast\" class=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n\n<script>\n(function(){\n  var baseUrl = location.origin;\n  var els = {};\n  function $(s){ return document.querySelector(s); }\n  function $all(s){ return Array.prototype.slice.call(document.querySelectorAll(s)); }\n  els.baseUrl = $('#baseUrl');\n  els.envInline = $('#envInline');\n  els.latencyHero = $('#latencyHero');\n  els.lastCheck = $('#lastCheck');\n  els.serviceName = $('#serviceName');\n  els.serviceVersion = $('#serviceVersion');\n  els.uptimeHero = $('#uptimeHero');\n  els.timestampHero = $('#timestampHero');\n  els.statusPill = $('#statusPill');\n  els.statusText = $('#statusText');\n  els.mongoBadge = $('#mongoBadge');\n  els.mongoValue = $('#mongoValue');\n  els.mongoDbName = $('#mongoDbName');\n  els.mongoLatency = $('#mongoLatency');\n  els.watchedValue = $('#watchedValue');\n  els.hashValue = $('#hashValue');\n  els.realtimeTs = $('#realtimeTs');\n  els.corsValue = $('#corsValue');\n  els.corsOrigins = $('#corsOrigins');\n  els.envValue = $('#envValue');\n  els.platformValue = $('#platformValue');\n  els.healthJson = $('#healthJson');\n  els.healthStatus = $('#healthStatus');\n  els.healthLatency = $('#healthLatency');\n  els.kvService = $('#kvService');\n  els.kvMongo = $('#kvMongo');\n  els.kvUptime = $('#kvUptime');\n  els.kvTimestamp = $('#kvTimestamp');\n  els.kvNode = $('#kvNode');\n  els.versionsList = $('#versionsList');\n  els.sseLog = $('#sseLog');\n  els.systemEnvDesc = $('#systemEnvDesc');\n  els.log = $('#log');\n  els.toast = $('#toast');\n  els.footService = $('#footService');\n  els.footEnv = $('#footEnv');\n  els.footTime = $('#footTime');\n\n  // Theme\n  var themeToggle = $('#themeToggle');\n  var iconSun = $('#iconSun');\n  var iconMoon = $('#iconMoon');\n  function applyTheme(t){\n    document.documentElement.setAttribute('data-theme', t);\n    localStorage.setItem('orl-backend-theme', t);\n    var isDark = t === 'dark';\n    iconSun.style.display = isDark ? 'none' : 'block';\n    iconMoon.style.display = isDark ? 'block' : 'none';\n    document.querySelector('meta[name=\"theme-color\"]').setAttribute('content', isDark ? '#0b1220' : '#4f46e5');\n  }\n  var saved = localStorage.getItem('orl-backend-theme');\n  var prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;\n  applyTheme(saved || (prefersDark ? 'dark' : 'light'));\n  themeToggle.addEventListener('click', function(){\n    var cur = document.documentElement.getAttribute('data-theme');\n    applyTheme(cur === 'dark' ? 'light' : 'dark');\n  });\n\n  // Base URL\n  els.baseUrl.textContent = baseUrl;\n  $('#btnCopyBaseUrl').addEventListener('click', function(){ copyText(baseUrl); });\n\n  // Tabs\n  $all('.tab').forEach(function(btn){\n    btn.addEventListener('click', function(){\n      var tab = btn.getAttribute('data-tab');\n      $all('.tab').forEach(function(b){ b.classList.remove('active'); b.setAttribute('aria-selected','false'); });\n      btn.classList.add('active'); btn.setAttribute('aria-selected','true');\n      $all('.panel').forEach(function(p){ p.classList.toggle('active', p.getAttribute('data-panel')===tab); });\n    });\n  });\n  // Search\n  var search = $('#apiSearch');\n  search.addEventListener('input', function(){\n    var q = search.value.trim().toLowerCase();\n    $all('.endpoint').forEach(function(ep){\n      var kw = (ep.getAttribute('data-keywords')||'') + ' ' + ep.textContent.toLowerCase();\n      ep.style.display = !q || kw.indexOf(q)!==-1 ? '' : 'none';\n    });\n  });\n\n  function toast(msg){\n    els.toast.textContent = msg;\n    els.toast.classList.add('show');\n    clearTimeout(toast._t);\n    toast._t = setTimeout(function(){ els.toast.classList.remove('show'); }, 2200);\n  }\n  function copyText(t){\n    var txt = t.replace(/BASE/g, baseUrl);\n    if(navigator.clipboard && navigator.clipboard.writeText){\n      navigator.clipboard.writeText(txt).then(function(){ toast('Copié !'); }, function(){ fallbackCopy(txt); });\n    } else fallbackCopy(txt);\n  }\n  function fallbackCopy(txt){\n    var ta=document.createElement('textarea'); ta.value=txt; ta.style.position='fixed'; ta.style.opacity='0';\n    document.body.appendChild(ta); ta.select(); try{document.execCommand('copy'); toast('Copié !');}catch(e){ toast('Copie échouée'); } ta.remove();\n  }\n  $all('[data-copy]').forEach(function(b){\n    b.addEventListener('click', function(){ copyText(b.getAttribute('data-copy')); });\n  });\n  $('#btnCopySse').addEventListener('click', function(){ copyText($('#btnCopySse').getAttribute('data-copy')); });\n\n  // Log\n  function log(msg, level){\n    var time = new Date().toLocaleTimeString();\n    var line = '['+time+'] ' + msg;\n    var div = document.createElement('div');\n    div.textContent = line;\n    div.style.color = level==='error' ? 'var(--danger)' : level==='ok' ? 'var(--success)' : 'var(--muted)';\n    div.style.borderBottom = '1px solid var(--border)';\n    div.style.padding = '4px 0';\n    if(els.log.textContent==='—') els.log.textContent='';\n    els.log.prepend(div);\n    // keep max 80\n    while(els.log.children.length>80) els.log.removeChild(els.log.lastChild);\n  }\n  $('#btnClearLog').addEventListener('click', function(){ els.log.textContent='—'; });\n  $('#btnCopyLog').addEventListener('click', function(){ copyText(els.log.innerText||els.log.textContent); });\n\n  // Format helpers\n  function fmtUptime(s){\n    if(s==null || isNaN(s)) return '—';\n    s = Math.floor(Number(s));\n    var d=Math.floor(s/86400), h=Math.floor((s%86400)/3600), m=Math.floor((s%3600)/60), sec=s%60;\n    if(d>0) return d+'j '+h+'h '+m+'m';\n    if(h>0) return h+'h '+m+'m '+sec+'s';\n    if(m>0) return m+'m '+sec+'s';\n    return sec+'s';\n  }\n  function fmtTime(ts){\n    try{ return new Date(ts).toLocaleString(); }catch(e){ return String(ts||'—'); }\n  }\n\n  // Try request\n  function doTry(method, path, body, token){\n    var url = path;\n    if(url.indexOf('http')!==0){\n      if(url.charAt(0)!=='/') url='/'+url;\n      url = baseUrl + url;\n    }\n    var headers = {};\n    if(token) headers['Authorization'] = 'Bearer ' + token.trim();\n    var opts = { method: method, headers: headers };\n    if(body && method!=='GET' && method!=='DELETE'){\n      headers['Content-Type']='application/json';\n      opts.body = body;\n    }\n    var start = performance.now();\n    return fetch(url, opts).then(function(res){\n      var ct = res.headers.get('content-type')||'';\n      var isJson = ct.indexOf('json')!==-1;\n      var p = isJson ? res.json().catch(function(){ return res.text(); }) : res.text();\n      return p.then(function(data){\n        var ms = Math.round(performance.now()-start);\n        return { ok: res.ok, status: res.status, data: data, ms: ms, url: url };\n      });\n    }).catch(function(err){\n      return { ok:false, status:0, data: { error: String(err && err.message || err) }, ms: Math.round(performance.now()-start), url:url };\n    });\n  }\n  $all('[data-try]').forEach(function(btn){\n    btn.addEventListener('click', function(){\n      var path = btn.getAttribute('data-try');\n      var method = btn.getAttribute('data-method')||'GET';\n      var token = $('#tokenInput').value;\n      var bodyInput = $('#tryBody').value.trim();\n      var body = null;\n      if((method==='POST'||method==='PUT'||method==='PATCH') && !bodyInput && path.indexOf('/api/auth')!==-1){\n        // provide minimal body hint\n        if(path==='/api/auth/signin' || path==='/api/auth/signup') body = JSON.stringify({ email:'test@example.com', password:'secret12', displayName:'Test'});\n        else if(path==='/api/contact') body = JSON.stringify({ name:'Test', email:'a@b.com', subject:'Support technique', message:'Hello depuis le dashboard'});\n      } else if(bodyInput) body = bodyInput;\n      $('#tryMethod').value = method;\n      $('#tryPath').value = path;\n      if(body) $('#tryBody').value = typeof body==='string' ? body : JSON.stringify(body,null,2);\n      executeTry();\n    });\n  });\n  function executeTry(){\n    var method = $('#tryMethod').value;\n    var path = $('#tryPath').value.trim()||'/api/health';\n    var body = $('#tryBody').value.trim()||null;\n    var token = $('#tokenInput').value;\n    $('#tryResult').textContent = '… envoi '+method+' '+path+' …';\n    doTry(method, path, body, token).then(function(r){\n      var pretty = '';\n      try{ pretty = typeof r.data==='string' ? r.data : JSON.stringify(r.data,null,2); }catch(e){ pretty = String(r.data); }\n      $('#tryResult').textContent = r.status+' '+ (r.ok?'OK':'ERR') +' • '+r.ms+'ms • '+r.url+'\\n\\n'+pretty;\n      log(method+' '+path+' → '+r.status+' ('+r.ms+'ms)', r.ok?'ok':'error');\n    });\n  }\n  $('#btnTryCustom').addEventListener('click', executeTry);\n\n  // Health polling\n  var lastLatency = null;\n  function fetchHealth(){\n    var t0 = performance.now();\n    return fetch(baseUrl + '/api/health', { cache:'no-store' }).then(function(res){\n      var ms = Math.round(performance.now()-t0);\n      lastLatency = ms;\n      if(!res.ok) throw new Error('HTTP '+res.status);\n      return res.json().then(function(data){\n        renderHealth(data, ms, null);\n        return data;\n      });\n    }).catch(function(err){\n      var ms = Math.round(performance.now()-t0);\n      renderHealth(null, ms, err);\n      return null;\n    });\n  }\n  function fetchMeta(){\n    return fetch(baseUrl + '/api/meta', { cache:'no-store' }).then(function(r){ return r.ok ? r.json() : null; }).then(function(data){\n      if(!data) return;\n      els.serviceName.textContent = data.service || 'orl-platform-dems-backend';\n      els.serviceVersion.textContent = 'v'+(data.version||'1.0.0')+' • Node '+ (data.nodeVersion||'—');\n      els.envValue.textContent = data.env || '—';\n      els.envInline.textContent = data.env || '—';\n      els.platformValue.textContent = (data.platform||'—') + ' • ' + (data.arch||'');\n      els.corsValue.textContent = String(data.corsOriginsCount ?? '—');\n      els.corsOrigins.textContent = (data.corsOrigins && data.corsOrigins.length) ? data.corsOrigins.slice(0,2).join(', ') + (data.corsOrigins.length>2 ? ' +' + (data.corsOrigins.length-2) : '') : 'localhost auto';\n      els.mongoDbName.textContent = data.mongoDbName || '—';\n      els.footService.textContent = data.service || '—';\n      els.footEnv.textContent = data.env || '—';\n      if(data.features){\n        var f = [];\n        if(data.features.googleAuth) f.push('Google OAuth: on');\n        else f.push('Google OAuth: off');\n        if(data.features.cloudinary) f.push('Cloudinary: on');\n        else f.push('Cloudinary: off');\n        if(data.features.mailer) f.push('SMTP: on');\n        else f.push('SMTP: off');\n        els.systemEnvDesc.textContent = f.join(' • ') + ' • JWT ' + (data.jwtExpiresIn||'7d');\n      }\n      // uptime fallback if health didn't provide\n      if(data.uptime!=null){\n        els.uptimeHero.textContent = fmtUptime(data.uptime);\n        els.kvUptime.textContent = fmtUptime(data.uptime) + ' ('+Math.floor(data.uptime)+'s)';\n      }\n      if(data.timestamp) {\n        els.timestampHero.textContent = fmtTime(data.timestamp);\n        els.kvTimestamp.textContent = fmtTime(data.timestamp);\n      }\n      if(data.nodeVersion) els.kvNode.textContent = data.nodeVersion;\n    }).catch(function(){});\n  }\n  function renderHealth(data, ms, err){\n    els.healthLatency.textContent = ms + ' ms';\n    els.latencyHero.textContent = ms + ' ms';\n    els.lastCheck.textContent = new Date().toLocaleTimeString();\n    els.footTime.textContent = new Date().toLocaleTimeString();\n    if(err || !data){\n      els.statusPill.classList.add('offline');\n      els.statusText.textContent = 'Hors ligne';\n      els.healthStatus.textContent = 'offline';\n      els.healthStatus.className = 'badge err';\n      els.mongoBadge.textContent = 'indisponible';\n      els.mongoBadge.className = 'badge err';\n      els.mongoValue.textContent = '—';\n      els.healthJson.textContent = 'Erreur: ' + (err && err.message || 'fetch failed');\n      els.kvService.textContent = '—';\n      els.kvMongo.textContent = '—';\n      log('health error: ' + (err && err.message || 'unknown'), 'error');\n      return;\n    }\n    var ok = !!data.ok;\n    els.statusPill.classList.toggle('offline', !ok);\n    els.statusText.textContent = ok ? 'En ligne' : 'Dégradé';\n    els.healthStatus.textContent = ok ? 'ok' : 'degraded';\n    els.healthStatus.className = 'badge ' + (ok ? 'ok' : 'warn');\n    els.healthJson.textContent = JSON.stringify(data, null, 2);\n    els.kvService.textContent = data.service || '—';\n    var mongoConnected = !!data.mongoConnected;\n    els.kvMongo.textContent = mongoConnected ? 'connecté ✓' : 'déconnecté ✗';\n    els.mongoBadge.textContent = mongoConnected ? 'connecté' : 'déconnecté';\n    els.mongoBadge.className = 'badge ' + (mongoConnected ? 'ok' : 'err');\n    els.mongoValue.textContent = mongoConnected ? 'Connecté' : 'Déconnecté';\n    els.mongoLatency.textContent = ms + ' ms';\n    if(data.uptime!=null){\n      els.uptimeHero.textContent = fmtUptime(data.uptime);\n      els.kvUptime.textContent = fmtUptime(data.uptime) + ' ('+Math.floor(data.uptime)+'s)';\n    }\n    if(data.timestamp){\n      els.timestampHero.textContent = fmtTime(data.timestamp);\n      els.kvTimestamp.textContent = fmtTime(data.timestamp);\n    }\n    if(data.service) els.serviceName.textContent = data.service;\n    if(data.version) els.serviceVersion.textContent = 'v'+data.version + (data.nodeVersion ? ' • Node ' + data.nodeVersion : '');\n    if(data.nodeVersion) els.kvNode.textContent = data.nodeVersion;\n    log('GET /api/health → '+(ok?'ok':'degraded')+' mongo='+mongoConnected+' '+ms+'ms', ok?'ok':'error');\n  }\n  $('#btnRefreshHealth').addEventListener('click', function(){ fetchHealth(); fetchMeta(); });\n  $('#btnCopyHealth').addEventListener('click', function(){ copyText(els.healthJson.textContent); });\n\n  // Versions\n  function fetchVersions(){\n    var t0=performance.now();\n    return fetch(baseUrl + '/api/realtime/versions', { cache:'no-store' }).then(function(r){\n      if(!r.ok) throw new Error('HTTP '+r.status);\n      return r.json();\n    }).then(function(data){\n      renderVersions(data, Math.round(performance.now()-t0));\n    }).catch(function(err){\n      els.versionsList.innerHTML = '<div style=\"padding:12px;color:var(--danger);font-size:13px\">Erreur versions: '+ (err && err.message || err) +'</div>';\n      log('versions error: '+(err&&err.message||err),'error');\n    });\n  }\n  function renderVersions(data, ms){\n    var hash = data._hash || '—';\n    var ts = data._ts || Date.now();\n    els.hashValue.textContent = hash;\n    els.realtimeTs.textContent = new Date(ts).toLocaleTimeString() + ' • '+ms+'ms';\n    var cols = ['videos','qcms','openQuestions','clinicalCases','diagrams','users','payments','notifications','supportChats','supportChatMessages','pedagogicalFeedback','clinicalCaseFeedback','appSettings'];\n    var html='';\n    cols.forEach(function(name){\n      var v = data[name] || { count:0, updatedAt:0 };\n      var t = v.updatedAt ? new Date(v.updatedAt).toLocaleString() : '—';\n      var count = v.count!=null ? v.count : '—';\n      html += '<div class=\"version-item\"><div><div class=\"version-name\">'+name+'</div><div class=\"version-meta\"><span>'+t+'</span></div></div><div style=\"text-align:right\"><div style=\"font-size:18px;font-weight:850;letter-spacing:-.02em\">'+count+'</div><div style=\"font-size:11px;color:var(--muted);font-weight:700\">docs</div></div></div>';\n    });\n    els.versionsList.innerHTML = html;\n    // update watched count\n    var total = 0; cols.forEach(function(c){ total += (data[c] && data[c].count) ? Number(data[c].count):0; });\n    // keep original 13 label but also show total docs\n    log('GET /api/realtime/versions → hash '+hash+' '+ms+'ms','ok');\n  }\n  $('#btnRefreshVersions').addEventListener('click', fetchVersions);\n\n  // SSE\n  var es = null;\n  var sseActive = false;\n  $('#btnSse').addEventListener('click', function(){\n    if(sseActive && es){\n      try{ es.close(); }catch(e){}\n      es=null; sseActive=false;\n      this.textContent='● SSE Stream';\n      this.classList.remove('primary');\n      els.sseLog.style.display='none';\n      log('SSE closed','ok');\n      return;\n    }\n    this.textContent='■ Stop SSE';\n    this.classList.add('primary');\n    els.sseLog.style.display='block';\n    els.sseLog.textContent='Connexion SSE…';\n    try{\n      es = new EventSource(baseUrl + '/api/realtime/stream');\n      sseActive=true;\n      es.onmessage = function(e){\n        try{\n          var d = JSON.parse(e.data);\n          var h = d._hash||'—';\n          els.sseLog.textContent = new Date().toLocaleTimeString()+' hash='+h+'\\n'+JSON.stringify(d,null,2);\n          renderVersions(d, 0);\n          log('SSE event hash='+h,'ok');\n        }catch(err){\n          els.sseLog.textContent = e.data;\n        }\n      };\n      es.onerror = function(){ log('SSE error','error'); els.sseLog.textContent += '\\n[error] connexion interrompue'; };\n      log('SSE connected to /api/realtime/stream','ok');\n    }catch(err){\n      log('SSE failed: '+err.message,'error');\n    }\n  });\n\n  // Polling\n  fetchHealth();\n  fetchMeta();\n  fetchVersions();\n  setInterval(fetchHealth, 5000);\n  setInterval(fetchMeta, 15000);\n  setInterval(fetchVersions, 4000);\n\n  // live clock\n  setInterval(function(){ els.footTime.textContent = new Date().toLocaleTimeString(); }, 1000);\n\n})();\n</script>\n</body>\n</html>\n";
